final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    int index = 2 * constantPoolEntryIndex;
    int length = classFileBuffer[index] << 8 | classFileBuffer[index + 1];
    index += 2;
    int charIndex = 0;
    int endIndex = index + length;
    while (index < endIndex) {
        int b = classFileBuffer[index++] & 0xFF;
        if (b < 0x80) {
            charBuffer[charIndex++] = (char) b;
        } else if ((b & 0xE0) == 0xC0) {
            if (index >= endIndex) throw new UTFDataFormatException();
            charBuffer[charIndex++] = (char) (((b & 0x1F) << 6) | (classFileBuffer[index++] & 0x3F));
        } else if ((b & 0xF0) == 0xE0) {
            if (index + 1 >= endIndex) throw new UTFDataFormatException();
            int c = classFileBuffer[index++];
            int d = classFileBuffer[index++];
            charBuffer[charIndex++] = (char) (((b & 0x0F) << 12) | ((c & 0x3F) << 6) | (d & 0x3F));
        } else {
            throw new UTFDataFormatException();
        }
    }
    return new String(charBuffer, 0, charIndex);
}

