protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, null, 0.0);
    }

    V startVertex = null;
    V endVertex = null;
    double weight = 0.0;

    for (E edge : tour) {
        if (startVertex == null) {
            startVertex = graph.getEdgeSource(edge);
        }
        endVertex = graph.getEdgeTarget(edge);
        weight += graph.getEdgeWeight(edge);
    }

    return new GraphWalk<>(graph, startVertex, endVertex, tour, weight);
}

