private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    int i = 0;
    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            if (i < input.length()) {
                c = input.charAt(i);
                switch (c) {
                    case 'n':
                        output.append('\n');
                        break;
                    case 'r':
                        output.append('\r');
                        break;
                    case 't':
                        output.append('\t');
                        break;
                    case 'b':
                        output.append('\b');
                        break;
                    case 'f':
                        output.append('\f');
                        break;
                    case '\\':
                        output.append('\\');
                        break;
                    case '"':
                        output.append('"');
                        break;
                    default:
                        output.append(c);
                        break;
                }
            }
        } else {
            output.append(c);
        }
        i++;
    }
    return output.toString();
}

